import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"[Глава 9] Приложение","description":"","frontmatter":{},"headers":[],"relativePath":"ru/document/level-0/ch09-appendix.md","filePath":"ru/document/level-0/ch09-appendix.md","lastUpdated":1777787579000}`),a={name:`ru/document/level-0/ch09-appendix.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="глава-9-приложение" tabindex="-1">[Глава 9] Приложение <a class="header-anchor" href="#глава-9-приложение" aria-label="Permalink to “[Глава 9] Приложение”">​</a></h1><h2 id="_1-индекс-основных-команд-linux-для-начинающих" tabindex="-1">1. Индекс основных команд Linux для начинающих <a class="header-anchor" href="#_1-индекс-основных-команд-linux-для-начинающих" aria-label="Permalink to “1. Индекс основных команд Linux для начинающих”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Номер</th><th style="text-align:left;">Название команды</th><th style="text-align:left;">Описание команды</th><th style="text-align:center;">Глава</th></tr></thead><tbody><tr><td style="text-align:center;"><code>cmd-01</code></td><td style="text-align:left;"><code>apt update</code></td><td style="text-align:left;">Обновление списка пакетов</td><td style="text-align:center;"><a href="./ch03-ssh.html">Глава о удаленном подключении</a></td></tr><tr><td style="text-align:center;"><code>cmd-02</code></td><td style="text-align:left;"><code>apt upgrade</code></td><td style="text-align:left;">Обновление пакетов системы</td><td style="text-align:center;"><a href="./ch03-ssh.html">Глава о удаленном подключении</a></td></tr><tr><td style="text-align:center;"><code>cmd-03</code></td><td style="text-align:left;"><code>nano</code></td><td style="text-align:left;">Текстовый редактор</td><td style="text-align:center;"><a href="./ch04-security.html">Глава о безопасности</a></td></tr><tr><td style="text-align:center;"><code>cmd-04</code></td><td style="text-align:left;"><code>systemctl restart</code></td><td style="text-align:left;">Перезапуск сервиса</td><td style="text-align:center;"><a href="./ch04-security.html">Глава о безопасности</a></td></tr><tr><td style="text-align:center;"><code>cmd-05</code></td><td style="text-align:left;"><code>adduser</code></td><td style="text-align:left;">Добавление пользователя</td><td style="text-align:center;"><a href="./ch04-security.html">Глава о безопасности</a></td></tr><tr><td style="text-align:center;"><code>cmd-06</code></td><td style="text-align:left;"><code>apt install</code></td><td style="text-align:left;">Установка пакета</td><td style="text-align:center;"><a href="./ch04-security.html">Глава о безопасности</a></td></tr><tr><td style="text-align:center;"><code>cmd-07</code></td><td style="text-align:left;"><code>visudo</code></td><td style="text-align:left;">Редактор для настройки sudo</td><td style="text-align:center;"><a href="./ch04-security.html">Глава о безопасности</a></td></tr><tr><td style="text-align:center;"><code>cmd-08</code></td><td style="text-align:left;"><code>sudo</code></td><td style="text-align:left;">Выполнение команды от имени root</td><td style="text-align:center;"><a href="./ch04-security.html">Глава о безопасности</a></td></tr><tr><td style="text-align:center;"><code>cmd-09</code></td><td style="text-align:left;"><code>chmod</code></td><td style="text-align:left;">Изменение прав доступа к файлу/папке</td><td style="text-align:center;"><a href="./ch04-security.html">Глава о безопасности</a></td></tr><tr><td style="text-align:center;"><code>cmd-10</code></td><td style="text-align:left;"><code>mkdir</code></td><td style="text-align:left;">Создание папки</td><td style="text-align:center;"><a href="./ch05-webpage.html">Глава о создании сайта</a></td></tr><tr><td style="text-align:center;"><code>cmd-11</code></td><td style="text-align:left;"><code>systemctl reload</code></td><td style="text-align:left;">Перезагрузка конфигурации сервиса</td><td style="text-align:center;"><a href="./ch05-webpage.html">Глава о создании сайта</a></td></tr><tr><td style="text-align:center;"><code>cmd-12</code></td><td style="text-align:left;"><code>wget</code></td><td style="text-align:left;">Загрузка файла/страницы из сети</td><td style="text-align:center;"><a href="./ch06-certificates.html">Глава об управлении сертификатами</a></td></tr><tr><td style="text-align:center;"><code>cmd-13</code></td><td style="text-align:left;"><code>acme.sh</code></td><td style="text-align:left;">Управление сертификатами с помощью acme.sh</td><td style="text-align:center;"><a href="./ch06-certificates.html">Глава об управлении сертификатами</a></td></tr><tr><td style="text-align:center;"><code>cmd-14</code></td><td style="text-align:left;"><code>rm</code></td><td style="text-align:left;">Удаление файлов/папок</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr><tr><td style="text-align:center;"><code>cmd-15</code></td><td style="text-align:left;"><code>touch</code></td><td style="text-align:left;">Создание пустого файла</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr><tr><td style="text-align:center;"><code>cmd-16</code></td><td style="text-align:left;"><code>systemctl</code></td><td style="text-align:left;">Базовые команды управления сервисами systemd</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr><tr><td style="text-align:center;"><code>cmd-17</code></td><td style="text-align:left;"><code>reboot</code></td><td style="text-align:left;">Перезагрузка Linux</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr></tbody></table><h2 id="_2-индекс-важных-конфигурационных-фаилов-linux" tabindex="-1">2. Индекс важных конфигурационных файлов Linux <a class="header-anchor" href="#_2-индекс-важных-конфигурационных-фаилов-linux" aria-label="Permalink to “2. Индекс важных конфигурационных файлов Linux”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Номер</th><th style="text-align:left;">Расположение файла</th><th style="text-align:left;">Описание файла</th><th style="text-align:center;">Глава</th></tr></thead><tbody><tr><td style="text-align:center;"><code>conf-01</code></td><td style="text-align:left;"><code>/etc/ssh/sshd_config</code></td><td style="text-align:left;">Конфигурация SSH сервера</td><td style="text-align:center;"><a href="./ch03-ssh.html">Глава о удаленном подключении</a></td></tr><tr><td style="text-align:center;"><code>conf-02</code></td><td style="text-align:left;"><code>/etc/nginx/nginx.conf</code></td><td style="text-align:left;">Конфигурация Nginx</td><td style="text-align:center;"><a href="./ch05-webpage.html">Глава о создании сайта</a></td></tr><tr><td style="text-align:center;"><code>conf-03</code></td><td style="text-align:left;"><code>/etc/sysctl.d/99-bbr.conf</code></td><td style="text-align:left;">Пользовательские настройки ядра Linux</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr></tbody></table><h2 id="_3-индекс-важных-фаилов-xray" tabindex="-1">3. Индекс важных файлов Xray <a class="header-anchor" href="#_3-индекс-важных-фаилов-xray" aria-label="Permalink to “3. Индекс важных файлов Xray”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Номер</th><th style="text-align:left;">Расположение файла</th><th style="text-align:left;">Описание файла</th><th style="text-align:center;">Глава</th></tr></thead><tbody><tr><td style="text-align:center;"><code>xray-01</code></td><td style="text-align:left;"><code>/usr/local/etc/xray/config.json</code></td><td style="text-align:left;">Конфигурация Xray</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr><tr><td style="text-align:center;"><code>xray-02</code></td><td style="text-align:left;"><code>/home/vpsadmin/xray_cert/xray.cert</code></td><td style="text-align:left;">TLS сертификат</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr><tr><td style="text-align:center;"><code>xray-03</code></td><td style="text-align:left;"><code>/home/vpsadmin/xray_cert/xray.key</code></td><td style="text-align:left;">TLS ключ</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr><tr><td style="text-align:center;"><code>xray-04</code></td><td style="text-align:left;"><code>/home/vpsadmin/xray_log/access.log</code></td><td style="text-align:left;">Лог доступа Xray</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr><tr><td style="text-align:center;"><code>xray-05</code></td><td style="text-align:left;"><code>/home/vpsadmin/xray_log/error.log</code></td><td style="text-align:left;">Лог ошибок Xray</td><td style="text-align:center;"><a href="./ch07-xray-server.html">Глава о Xray сервере</a></td></tr></tbody></table>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};